package com.adria.transaction.domain;import jakarta.persistence.*;import java.util.*;import java.math.*;import java.time.*;
@Entity @Table(name="bank_transactions") public class BankTransaction {@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@Column(nullable=false) private UUID accountId;@Column(nullable=false,precision=19,scale=2) private BigDecimal amount;@Column(nullable=false,length=3) private String currency;private String merchantCategory;private String country;private Instant createdAt;
 public BankTransaction(){} public UUID getId(){return id;}public UUID getAccountId(){return accountId;}public void setAccountId(UUID v){accountId=v;}public BigDecimal getAmount(){return amount;}public void setAmount(BigDecimal v){amount=v;}public String getCurrency(){return currency;}public void setCurrency(String v){currency=v;}public String getMerchantCategory(){return merchantCategory;}public void setMerchantCategory(String v){merchantCategory=v;}public String getCountry(){return country;}public void setCountry(String v){country=v;}public Instant getCreatedAt(){return createdAt;}public void setCreatedAt(Instant v){createdAt=v;}}
